sp_widget.client_script:
function($scope, $rootScope, $timeout) {
    // Ano atual (como número)
    $scope.anoAtual = new Date().getFullYear(); 
    $scope.anoSelecionado = "";

    // Popula $scope.anos com os dados buscados no servidor (GlideRecord)
    $scope.anos = []; 
    if ($scope.data && $scope.data.anos) {
        $scope.anos = $scope.data.anos;
    } else {
        console.error("RANKING: O array de anos não foi carregado do servidor.");
    }

    // Função disparada ao mudar o ano selecionado no select
    $scope.anoChanged = function() {
        if ($scope.anoSelecionado && ($scope.anoSelecionado < 2000 || $scope.anoSelecionado > $scope.anoAtual)) {
            console.warn("Ano fora do intervalo permitido.");
            return;
        }
        $rootScope.$broadcast('anoSelecionado', $scope.anoSelecionado);
        console.log('Ano selecionado ranking:', $scope.anoSelecionado);
    };

    // Lógica de inicialização do ano
    $timeout(function() {
        // Converte o ano atual para String para garantir a comparação
        var anoParaInicializar = $scope.anoAtual.toString(); 
        var anosDisponiveis = $scope.anos;
        var inicializado = false;

        // 1. Tenta inicializar com o ANO ATUAL (ex: "2025")
        if (anosDisponiveis.includes(anoParaInicializar)) {
            $scope.anoSelecionado = anoParaInicializar;
            console.log('RANKING: Inicialização automática: Ano Atual (' + anoParaInicializar + ') selecionado.');
            inicializado = true;
        } 
        // 2. Se o ano atual não existir, inicializa com o ano mais recente disponível
        else if (anosDisponiveis.length > 0) {
            $scope.anoSelecionado = anosDisponiveis[0];
            console.log('RANKING: Inicialização automática: Ano Mais Recente (' + $scope.anoSelecionado + ') selecionado.');
            inicializado = true;
        } 

        // 3. Se nenhuma das opções anteriores funcionar, volta para "Todos"
        if (!inicializado) {
            $scope.anoSelecionado = "";
            console.log('RANKING: Inicialização automática: "Todos os anos" selecionado.');
        }

        // Dispara o evento com o valor inicial (Ano Atual, Mais Recente ou Todos)
        $scope.anoChanged();
    });
}

sp_widget.css:
@import url('https://fonts.googleapis.com/css2?family=Roboto+Flex:opsz,wght@8..144,400;600&display=swap');

.breadcrumb-bar {
    font-family: "Roboto Flex", sans-serif;
    display: flex;
    align-items: center;
    justify-content: space-between;
    background-color: #f8faff;
    border-radius: .6rem;
    padding: .8rem 1.5rem;
    color: #1e3a8a;
    font-size: 24px;
    box-shadow: 0 .1rem .2rem rgba(0, 0, 0, .05);
}

.breadcrumb-links {
    display: flex;
    align-items: center;
    gap: 6px;
}

.breadcrumb-links a {
    color: #2563eb;
    text-decoration: none;
    font-weight: 500;
}

.breadcrumb-links a:hover {
    text-decoration: underline;
}

.breadcrumb-links span {
    color: #64748b;
}

/* --- Filtro de Ano --- */
.breadcrumb-filter {
    display: flex;
    flex-direction: column;
    align-items: flex-start;
    gap: 2px;
}

.breadcrumb-filter label {
    font-size: 10px;
    font-weight: 600;
    color: #293273;
    //letter-spacing: 0.5px;
    display: flex;
    align-items: center;
    margin-left: 26px;
  	margin-bottom: -2px;
}

.filter-group {
    display: flex;
    align-items: center;
    gap: 8px;
}

.filter-group i {
    color: #4b5563;
    font-size: 13px;
}

/* Select com ícone interno e seta customizada */
.filter-select {
    position: relative;
    display: flex;
    align-items: center;
    z-index: 9999;
}

/* Ícone de filtro à esquerda */
.filter-select i {
    color: white;
    -webkit-text-stroke: 1px #293273;
    font-size: 16px;
    pointer-events: none;
  	padding-right: 10px;
}

/* Seta para baixo*/
.filter-select::after {
    content: "v";
    position: absolute;
    right: 10px;
    top: 50%;
    transform: translateY(-50%) scaleY(0.9) scaleX(1.6);
    font-size: 14px;
    font-weight: 400;
    pointer-events: none;
  	color: #0f0f0f;
}

/* Select estilizado */
.filter-select select {
    padding: 4px 26px 4px 8px;
    border: 1px solid #cbd5e1;
    border-radius: 6px;
    background-color: white;
    font-family: 'Roboto Flex', sans-serif;
    font-size: 13px;
    color: #334155;
    appearance: none;
    min-width: 90px;
    cursor: pointer;
    height: 28px;
    display: flex;
    align-items: center;
}

.filter-select select:focus {
    outline: none;
    border-color: #2563eb;
    box-shadow: 0 0 0 2px rgba(37,99,235,0.2);
}

@media (min-width: 375px) and (max-width: 819px) {
    .breadcrumb-bar {
        font-size: 1.5rem;
    }
}

@media (min-width: 820px) {
    .breadcrumb-bar {
        font-size: 2.5rem;
    }
}

sp_widget.script:
(function() {

	data.instanceName = gs.getProperty('instance_name');
	data.pageId = options.page_id || 'resultados_fiscais';

    var anos = [];
    var gr = new GlideRecord('x_sded9_portal_t_0_dados_do_ranking');
    gr.orderByDesc('u_ano');
    gr.query();

    var anosUnicos = {};
    while (gr.next()) {
        var ano = gr.getValue('u_ano');
        if (ano) { 
            if (!anosUnicos[ano]) {
                anos.push(ano);
                anosUnicos[ano] = true;
            }
        }
    }

    // gs.addInfoMessage(JSON.stringify(anos))

    data.anos = anos; 
})();
